{
    return cpv(s.width, s.height);
}

Rect PhysicsHelper::cpbb2rect(const cpBB& bb)
{
    return Rect(static_cast<float>(bb.l),
                static_cast<float>(bb.b),
                static_cast<float>(bb.r - bb.l),
                static_cast<float>(bb.t - bb.b));
}

cpBB PhysicsHelper::rect2cpbb(const Rect& r)
{
    return cpBBNew(r.getMinX(), r.getMinY(), r.getMaxX(), r.getMaxY());
